{
  "criteria": [
    {
      "id": "content",
      "score": 14,
      "max": 22,
      "comment": "Where, with whom and what are mentioned; «що сподобалося» is only «погода», thin."
    },
    {
      "id": "form",
      "score": 2,
      "max": 4,
      "comment": "One block of text; no real opening or closing."
    },
    {
      "id": "fit",
      "score": 6,
      "max": 9,
      "comment": "On topic, but the account is a list of short facts."
    },
    {
      "id": "coherence",
      "score": 12,
      "max": 26,
      "comment": "Mostly «і … і»; «Потом» is Russian and breaks the flow."
    },
    {
      "id": "norms",
      "score": 10,
      "max": 26,
      "comment": "Many Russianisms: «В воскресенье», «кушали», «нравилось», «Потом», «подарок», plus case errors («в парк», «з друг»)."
    },
    {
      "id": "richness",
      "score": 3,
      "max": 9,
      "comment": "Very limited vocabulary, repetition of «ми»."
    },
    {
      "id": "volume",
      "score": 2,
      "max": 4,
      "comment": "About 27 words, well under the 50-word minimum."
    }
  ],
  "corrected": "У неділю я був у парку з другом. Ми гуляли й їли морозиво. Мені подобалася погода. Потім ми ходили до магазину й купили подарунок.",
  "changes": [
    {
      "before": "В воскресенье",
      "after": "У неділю",
      "explanation": "Russianism: «неділя» is Sunday in Ukrainian; accusative after «у»."
    },
    {
      "before": "в парк з друг",
      "after": "у парку з другом",
      "explanation": "Locative after «у» for a place you are in, instrumental «з другом» after «з»."
    },
    {
      "before": "кушали",
      "after": "їли",
      "explanation": "«Кушати» is a Russianism; use «їсти»."
    },
    {
      "before": "нравилось",
      "after": "подобалася",
      "explanation": "«Подобатися» is the Ukrainian verb; it agrees with «погода» (feminine)."
    },
    {
      "before": "Потом",
      "after": "Потім",
      "explanation": "Russianism: Ukrainian «потім»."
    },
    {
      "before": "подарок",
      "after": "подарунок",
      "explanation": "Russianism: Ukrainian «подарунок»."
    }
  ],
  "tips": [
    "List the Russian-looking words you use and learn their Ukrainian twins.",
    "Write at least 50 words: add where, who, what and what you liked in full sentences."
  ]
}
